# -*- coding: utf-8 -*-
"""Generateur bts(pi)-mat-part-A.json — lot A (Droit, Management).

20 fiches au format 'fiche prototype' pour la filiere bts-pi (BTS1 / BTS2) :
12 points de cours, 10 questions corrigees (8 QCM + 2 texte), 7 blocs en ordre
strict, 3 schemas SVG. Reference : arrete du 23 juillet 2015 (BTS professions
immobilieres), loi Hoguet du 2 janvier 1970, decret du 20 juillet 1972,
Code civil, Code de l'urbanisme, loi du 10 juillet 1965, eduscol.
"""
import os
import sys
sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
from fixtures import (fiche, qcm, qt, diag, svg_grille, svg_flux, svg_etapes,
                      svg_compare, bloc, valider_et_ecrire)

REF = ("Référentiel BTS « professions immobilières », arrêté du 23 juillet 2015 (Bulletin officiel) · "
       "loi n° 70-9 du 2 janvier 1970 et décret du 20 juillet 1972 · Code civil, Code de l'urbanisme, "
       "loi du 10 juillet 1965 · éduscol, ressources BTS immobilier")
FIL = ["bts-pi"]
F = []


def A(code, titre, mat, ans, pts, qs, eq, leg, grille, etapes, cmpG, cmpD,
      pieges, exemples, flux=None, src=""):
    """Ajoute une fiche complete ; les 7 blocs sont construits dans l'ordre impose."""
    aff = [
        bloc("L'idée en une phrase", texte=pts[0], type="intro"),
        bloc("La règle ou formule clé", eq=eq, leg=leg, type="formule"),
        bloc("Tableau de synthèse", items=grille, type="grille"),
        bloc("À retenir pour l'examen", items=pts[3:8], type="liste"),
        bloc("La méthode en cinq étapes", items=etapes, type="etapes"),
        bloc("Pièges fréquents", items=pieges, type="attention"),
        bloc("Exemples à refaire", items=exemples, type="exemples"),
    ]
    sc = [
        diag("1 · " + code + " · repères", svg_grille(code + " · repères", ["Notion", "Sens", "Usage"], grille)),
        diag("2 · " + code + " · démarche", svg_etapes(code + " · méthode", etapes)),
    ]
    if flux:
        sc.append(diag("3 · " + code + " · enchaînement", svg_flux(code + " · chaîne", flux)))
    else:
        sc.append(diag("3 · " + code + " · deux lectures", svg_compare(code + " · comparaison", cmpG, cmpD)))
    source = REF + (" · " + src if src else "")
    F.append(fiche(FIL, ans, mat, code + ". " + titre, source, pts, qs, aff, sc))


